  const first = joinVersioned(events, t);
  assert.equal(first[0].dim.tier, 'A');
  t.upsert('u1', { tier: 'A+' }, 1500);
  const corrections = rejoinLateDimension(events, t);
  assert.ok(corrections.length >= 1);
