+  ctx.fillText(`t=${minTime}`, padding, height - 12);
+  ctx.fillText(`t=${maxTime}`, width - padding - 42, height - 12);
+
+  for (const record of engine.dimensions) {
+    const x = xFor(record.ts);
+    ctx.fillStyle = '#f4b860';
