    23	function drawTimeline(canvas, engine) {
    24	  if (!canvas || typeof canvas.getContext !== 'function') return;
    25	  const ctx = canvas.getContext('2d');
    26	  if (!ctx) return;
    27	  const width = canvas.width;
    28	  const height = canvas.height;
    29	  const padding = 36;
    30	  const records = [
    31	    ...engine.dimensions.map((record) => ({ ...record, kind: 'dimension' })),
    32	    ...engine.events.map((record) => ({ ...record, kind: 'event' })),
    33	  ];
    34	
    35	  ctx.clearRect(0, 0, width, height);
    36	  ctx.fillStyle = '#18212b';
    37	  ctx.fillRect(0, 0, width, height);
    38	
    39	  if (records.length === 0) {
    40	    ctx.fillStyle = '#8fa3b8';
    41	    ctx.fillText('Load fixtures to draw the event-time timeline', padding, padding);
    42	    return;
    43	  }
    44	
    45	  const times = records.map((record) => record.ts);
    46	  const minTime = Math.min(...times);
    47	  const maxTime = Math.max(...times, engine.stats.watermark);
    48	  const span = Math.max(1, maxTime - minTime);
    49	  const xFor = (ts) => padding + ((ts - minTime) / span) * (width - padding * 2);
    50	
    51	  ctx.strokeStyle = '#334456';
    52	  ctx.lineWidth = 1;
    53	  ctx.beginPath();
    54	  ctx.moveTo(padding, height / 2);
    55	  ctx.lineTo(width - padding, height / 2);
    56	  ctx.stroke();
    57	
    58	  ctx.fillStyle = '#8fa3b8';
    59	  ctx.font = '12px ui-sans-serif, system-ui';
    60	  ctx.fillText(`t=${minTime}`, padding, height - 12);
    61	  ctx.fillText(`t=${maxTime}`, width - padding - 42, height - 12);
    62	
    63	  for (const record of engine.dimensions) {
    64	    const x = xFor(record.ts);
    65	    ctx.fillStyle = '#f4b860';
    66	    ctx.fillRect(x - 3, padding, 6, height / 2 - padding);
    67	    ctx.fillStyle = '#f4b860';
    68	    ctx.fillText(`dim ${record.key}`, x - 18, padding - 8);
    69	  }
    70	
    71	  engine.events.forEach((record, index) => {
    72	    const x = xFor(record.ts);
    73	    const y = height / 2 + 18 + (index % 2) * 24;
    74	    ctx.fillStyle = '#58c7ff';
    75	    ctx.beginPath();
    76	    ctx.arc(x, y, 5, 0, Math.PI * 2);
    77	    ctx.fill();
    78	    ctx.fillStyle = '#c9d7e5';
    79	    ctx.fillText(String(record.id ?? index), x - 3, y + 20);
    80	  });
    81	
    82	  if (engine.stats.watermark > 0) {
    83	    const x = xFor(engine.stats.watermark);
    84	    ctx.strokeStyle = '#95e0a4';
    85	    ctx.setLineDash([6, 4]);
    86	    ctx.beginPath();
    87	    ctx.moveTo(x, padding - 12);
    88	    ctx.lineTo(x, height - padding);
    89	    ctx.stroke();
    90	    ctx.setLineDash([]);
    91	    ctx.fillStyle = '#95e0a4';
    92	    ctx.fillText('watermark', x - 28, padding - 16);
    93	  }
    94	}
