    96	function exportResults(results) {
    97	  const blob = new Blob([JSON.stringify(results, null, 2)], { type: 'application/json' });
    98	  const url = URL.createObjectURL(blob);
    99	  const anchor = document.createElement('a');
   100	  anchor.href = url;
   101	  anchor.download = 'temporal-join-results.json';
   102	  anchor.click();
   103	  URL.revokeObjectURL(url);
   104	}
