   106	export function bindControls(ctx) {
   107	  const root = ctx.root ?? document;
   108	  const latenessInput = ctx.latenessInput ?? root.querySelector('[data-key="lateness"]');
   109	  const loadButton = ctx.loadButton ?? root.querySelector('#btn-load');
   110	  const runButton = ctx.runButton ?? root.querySelector('#btn-run');
   111	  const exportButton = ctx.exportButton ?? root.querySelector('#btn-export');
   112	  const engine = ctx.engine ?? new JoinEngine({
   113	    allowedLatenessMs: Number(latenessInput?.value ?? 0),
   114	  });
   115	
   116	  renderResults(ctx.results, engine.results);
   117	  renderStats(ctx.stats, engine.stats);
   118	  drawTimeline(ctx.canvas, engine);
   119	
   120	  if (loadButton) {
   121	    loadButton.addEventListener('click', async () => {
   122	      try {
   123	        setStatus(ctx.status, 'loading');
   124	        engine.setAllowedLateness(latenessInput?.value ?? engine.allowedLatenessMs);
   125	        await engine.loadFixtures();
   126	        renderResults(ctx.results, []);
   127	        drawTimeline(ctx.canvas, engine);
   128	        setStatus(ctx.status, 'ready');
   129	      } catch (error) {
   130	        setStatus(ctx.status, `error: ${error.message || error}`);
   131	      }
   132	    });
   133	  }
   134	
   135	  if (runButton) {
   136	    runButton.addEventListener('click', async () => {
   137	      try {
   138	        setStatus(ctx.status, 'running');
   139	        engine.setAllowedLateness(latenessInput?.value ?? engine.allowedLatenessMs);
   140	        const results = await engine.run();
   141	        renderResults(ctx.results, results);
   142	        renderStats(ctx.stats, engine.stats);
   143	        drawTimeline(ctx.canvas, engine);
   144	        setStatus(ctx.status, 'ready');
   145	      } catch (error) {
   146	        setStatus(ctx.status, `error: ${error.message || error}`);
   147	      }
   148	    });
   149	  }
   150	
   151	  if (exportButton) {
   152	    exportButton.addEventListener('click', () => {
   153	      try {
   154	        if (engine.results.length === 0) {
   155	          setStatus(ctx.status, 'Run the join before exporting');
   156	          return;
   157	        }
   158	        exportResults(engine.results);
   159	        setStatus(ctx.status, 'ready');
   160	      } catch (error) {
   161	        setStatus(ctx.status, `error: ${error.message || error}`);
   162	      }
   163	    });
   164	  }
   165	
   166	  return engine;
   167	}
